// Parse PM output dan siapkan untuk Code Analyzer
const pmOutput = $input.first().json;
let pmContent = '';

if (pmOutput.content && Array.isArray(pmOutput.content)) {
  pmContent = pmOutput.content.map(c => c.text || '').join('');
} else if (typeof pmOutput === 'string') {
  pmContent = pmOutput;
} else {
  pmContent = JSON.stringify(pmOutput);
}

// Coba parse JSON dari output PM
let parsedTask = {};
try {
  const jsonMatch = pmContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedTask = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  parsedTask = { raw_output: pmContent };
}

return [{
  json: {
    pm_output: pmContent,
    parsed_task: parsedTask,
    timestamp: new Date().toISOString(),
    workflow_phase: 'pre_execution_analysis'
  }
}];

// Konsolidasi output PM + CA untuk diteruskan ke developer agents
const pmData = $('parse-pm-output').first().json;
const caOutput = $input.first().json;

let caContent = '';
if (caOutput.content && Array.isArray(caOutput.content)) {
  caContent = caOutput.content.map(c => c.text || '').join('');
} else {
  caContent = JSON.stringify(caOutput);
}

let caReport = {};
try {
  const jsonMatch = caContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) caReport = JSON.parse(jsonMatch[0]);
} catch(e) {
  caReport = { raw_output: caContent };
}

return [{
  json: {
    pm_instructions: pmData.pm_output,
    ca_report: caContent,
    ca_clearance: caReport.clearance_status || 'CLEAR',
    consolidated_context: `PM INSTRUCTIONS:\n${pmData.pm_output}\n\nCODE ANALYZER REPORT:\n${caContent}`,
    timestamp: new Date().toISOString()
  }
}];

// Parse dan simpan output DB Engineer
const dbOutput = $input.first().json;
let dbContent = '';

if (dbOutput.content && Array.isArray(dbOutput.content)) {
  dbContent = dbOutput.content.map(c => c.text || '').join('');
} else {
  dbContent = JSON.stringify(dbOutput);
}

return [{
  json: {
    db_engineer_output: dbContent,
    agent: 'DB_ENGINEER',
    status: 'COMPLETED',
    timestamp: new Date().toISOString()
  }
}];

const beOutput = $input.first().json;
let beContent = '';

if (beOutput.content && Array.isArray(beOutput.content)) {
  beContent = beOutput.content.map(c => c.text || '').join('');
} else {
  beContent = JSON.stringify(beOutput);
}

return [{
  json: {
    backend_output: beContent,
    agent: 'BACKEND',
    status: 'COMPLETED',
    timestamp: new Date().toISOString()
  }
}];

const feOutput = $input.first().json;
let feContent = '';

if (feOutput.content && Array.isArray(feOutput.content)) {
  feContent = feOutput.content.map(c => c.text || '').join('');
} else {
  feContent = JSON.stringify(feOutput);
}

return [{
  json: {
    frontend_output: feContent,
    agent: 'FRONTEND',
    status: 'COMPLETED',
    timestamp: new Date().toISOString()
  }
}];

// Tunggu semua agent selesai lalu gabungkan
const dbOutput = $('parse-db-output').first().json;
const beOutput = $('parse-be-output').first().json;
const feOutput = $('parse-fe-output').first().json;

const allCompleted = [
  dbOutput.status === 'COMPLETED',
  beOutput.status === 'COMPLETED',
  feOutput.status === 'COMPLETED'
].every(Boolean);

return [{
  json: {
    all_agents_completed: allCompleted,
    db_output: dbOutput.db_engineer_output,
    be_output: beOutput.backend_output,
    fe_output: feOutput.frontend_output,
    combined_for_qa: `
=== DB ENGINEER OUTPUT ===
${dbOutput.db_engineer_output}

=== BACKEND DEVELOPER OUTPUT ===
${beOutput.backend_output}

=== FRONTEND DEVELOPER OUTPUT ===
${feOutput.frontend_output}
    `,
    timestamp: new Date().toISOString()
  }
}];

