const qaOutput = $input.first().json;
let qaContent = '';

if (qaOutput.content && Array.isArray(qaOutput.content)) {
  qaContent = qaOutput.content.map(c => c.text || '').join('');
} else {
  qaContent = JSON.stringify(qaOutput);
}

let qaReport = {};
try {
  const jsonMatch = qaContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) qaReport = JSON.parse(jsonMatch[0]);
} catch(e) {
  qaReport = { raw_output: qaContent, overall_status: 'NEEDS_REVIEW' };
}

const isApproved = qaReport.overall_status === 'APPROVED' ||
                   qaContent.toUpperCase().includes('APPROVED') && !qaContent.toUpperCase().includes('REJECTED');

return [{
  json: {
    qa_output: qaContent,
    qa_report: qaReport,
    is_approved: isApproved,
    qa_status: isApproved ? 'APPROVED' : 'REJECTED',
    timestamp: new Date().toISOString()
  }
}];

