// Final aggregator - kumpulkan semua hasil
const dbOut = $('parse-db-output').first().json;
const beOut = $('parse-be-output').first().json;
const feOut = $('parse-fe-output').first().json;
const qaOut = $('parse-qa-output').first().json;
const devopsOut = $('parse-devops-output').first().json;
const twOut = $('parse-tw-output').first().json;

const finalReport = {
  workflow_id: 'SPP_SEKOLAH_' + Date.now(),
  project: 'Sistem SPP Sekolah',
  version: '1.0',
  completion_timestamp: new Date().toISOString(),
  status: 'WORKFLOW_COMPLETED',
  qa_status: qaOut.qa_status,

  deliverables: {
    database: {
      agent: 'DB Engineer',
      status: dbOut.status,
      output_preview: dbOut.db_engineer_output ? dbOut.db_engineer_output.substring(0, 500) + '...' : 'N/A'
    },
    backend: {
      agent: 'Backend Developer',
      status: beOut.status,
      output_preview: beOut.backend_output ? beOut.backend_output.substring(0, 500) + '...' : 'N/A'
    },
    frontend: {
      agent: 'Frontend Developer',
      status: feOut.status,
      output_preview: feOut.frontend_output ? feOut.frontend_output.substring(0, 500) + '...' : 'N/A'
    },
    devops: {
      agent: 'DevOps',
      status: devopsOut.status,
      output_preview: devopsOut.devops_output ? devopsOut.devops_output.substring(0, 500) + '...' : 'N/A'
    },
    documentation: {
      agent: 'Tech Writer',
      status: twOut.status,
      output_preview: twOut.tech_writer_output ? twOut.tech_writer_output.substring(0, 500) + '...' : 'N/A'
    }
  },

  full_outputs: {
    db_engineer: dbOut.db_engineer_output,
    backend: beOut.backend_output,
    frontend: feOut.frontend_output,
    qa_report: qaOut.qa_output,
    devops: devopsOut.devops_output,
    tech_writer: twOut.tech_writer_output
  },

  next_steps: [
    '1. Review semua output yang dihasilkan',
    '2. Copy migration files ke folder database/migrations/',
    '3. Copy service files ke folder app/Services/',
    '4. Copy Filament resources ke app/Filament/Resources/',
    '5. Jalankan: composer install',
    '6. Setup .env dari .env.example',
    '7. Jalankan: php artisan migrate --seed',
    '8. Jalankan: php artisan filament:cache-components',
    '9. Jalankan: php artisan serve'
  ]
};

return [{ json: finalReport }];
